    public static void EnsureDirectories(){foreach(string path in new[]{Root,AppsDirectory,DriversDirectory,ReportsDirectory,ProfilesDirectory,Path.GetDirectoryName(HistoryFile)})Directory.CreateDirectory(path);}
    public static string Quote(string value){return "\""+value.Replace("\"","\\\"")+"\"";}
    public static string SafeName(string value){string clean=Regex.Replace(value??"","[^A-Za-z0-9áéíóúÁÉÍÓÚñÑ._-]+","-").Trim('-','.');return String.IsNullOrWhiteSpace(clean)?"perfil":clean;}
    public static CommandResult Capture(string file,string arguments,int timeout=120000){
      var info=new ProcessStartInfo(file,arguments){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};
      using(var process=Process.Start(info)){if(process==null)throw new IOException("Windows no pudo iniciar "+file+".");Task<string> output=process.StandardOutput.ReadToEndAsync(),error=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(timeout)){try{process.Kill();}catch{}throw new TimeoutException("La operación excedió el tiempo de espera.");}Task.WaitAll(new Task[]{output,error});return new CommandResult{ExitCode=process.ExitCode,Output=(output.Result+Environment.NewLine+error.Result).Trim()};}
    }
    public static int RunElevated(string file,string arguments){using(var process=Process.Start(new ProcessStartInfo(file,arguments){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Normal})){if(process==null)throw new IOException("Windows no pudo iniciar la operación administrativa.");process.WaitForExit();return process.ExitCode;}}
    public static bool HasWinget(){try{return Capture("where.exe","winget",10000).ExitCode==0;}catch{return false;}}
    public static List<string> ReadPackageIds(string file){string json=File.ReadAllText(file,Encoding.UTF8);return Regex.Matches(json,"\\\"PackageIdentifier\\\"\\s*:\\s*\\\"([^\\\"]+)\\\"").Cast<Match>().Select(m=>m.Groups[1].Value).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x).ToList();}

    public static void Record(string category,string action,string result,string path=null){
      try{EnsureDirectories();var entry=new Dictionary<string,object>{{"fecha",DateTime.Now.ToString("o")},{"categoria",category},{"accion",action},{"resultado",result},{"ruta",path??""},{"version",AppInfo.DisplayVersion}};File.AppendAllText(HistoryFile,new JavaScriptSerializer().Serialize(entry)+Environment.NewLine,Encoding.UTF8);}catch{}
    }

    public static List<string[]> ReadHistory(){
      var rows=new List<string[]>();if(!File.Exists(HistoryFile))return rows;
      foreach(string line in File.ReadLines(HistoryFile,Encoding.UTF8).Reverse().Take(250))try{var item=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(line);DateTime stamp;string raw=Convert.ToString(item["fecha"]);string date=DateTime.TryParse(raw,out stamp)?stamp.ToString("dd-MM-yyyy HH:mm"):raw;rows.Add(new[]{date,Convert.ToString(item["categoria"]),Convert.ToString(item["accion"]),Convert.ToString(item["resultado"]),Convert.ToString(item["ruta"])});}catch{}
      return rows;
    }

    public static bool PendingRestart(){
      string[] keys={@"SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending",@"SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired"};
      try{foreach(string path in keys)using(var key=Registry.LocalMachine.OpenSubKey(path))if(key!=null)return true;using(var session=Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Control\Session Manager"))return session!=null&&session.GetValue("PendingFileRenameOperations")!=null;}catch{return false;}
    }

    public static List<string[]> CheckSystem(){
      var result=new List<string[]>();
      bool winget=HasWinget();result.Add(new[]{winget?"Correcto":"Atención","WinGet",winget?"Disponible para exportar e importar aplicaciones.":"No está disponible todavía; abre Microsoft Store y actualiza App Installer."});
      try{var drive=new DriveInfo(Path.GetPathRoot(Environment.SystemDirectory));long gb=drive.AvailableFreeSpace/(1024L*1024L*1024L);result.Add(new[]{gb>=20?"Correcto":"Atención","Espacio del sistema",gb+" GB libres en "+drive.Name});}catch{result.Add(new[]{"Revisar","Espacio del sistema","No fue posible consultar la unidad."});}
      bool pending=PendingRestart();result.Add(new[]{pending?"Atención":"Correcto","Reinicio pendiente",pending?"Windows tiene operaciones pendientes de reinicio.":"No se detectaron indicadores habituales de reinicio pendiente."});
      string[] folders={Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads"),Environment.GetFolderPath(Environment.SpecialFolder.MyPictures),Environment.GetFolderPath(Environment.SpecialFolder.MyMusic),Environment.GetFolderPath(Environment.SpecialFolder.MyVideos)};
      string systemRoot=Path.GetPathRoot(Environment.SystemDirectory);int separated=folders.Count(path=>!String.IsNullOrWhiteSpace(path)&&!String.Equals(Path.GetPathRoot(path),systemRoot,StringComparison.OrdinalIgnoreCase));result.Add(new[]{separated>0?"Correcto":"Revisar","Carpetas personales",separated+" de 6 están separadas de la unidad del sistema."});
      try{var devices=Capture("pnputil.exe","/enum-devices /problem",30000);bool problems=devices.ExitCode==0&&Regex.IsMatch(devices.Output,"Problem Code|Código de problema",RegexOptions.IgnoreCase);result.Add(new[]{problems?"Atención":"Correcto","Dispositivos",problems?"PnPUtil informó dispositivos con problemas.":"No se detectaron dispositivos con problemas, o esta versión de Windows no entrega el detalle."});}catch{result.Add(new[]{"Revisar","Dispositivos","Abre el Administrador de dispositivos para comprobarlos."});}
      result.Add(new[]{NetworkInterface.GetIsNetworkAvailable()?"Correcto":"Atención","Conexión de red",NetworkInterface.GetIsNetworkAvailable()?"Windows informa una conexión disponible.":"No se detectó una conexión de red."});
      try{EnsureDirectories();int profiles=Directory.GetFiles(ProfilesDirectory,"*.json").Length;result.Add(new[]{profiles>0?"Correcto":"Revisar","Perfil de aplicaciones",profiles>0?profiles+" perfil(es) disponible(s).":"Aún no existe un perfil para recuperar aplicaciones."});int driverSets=Directory.GetDirectories(DriversDirectory).Count(path=>File.Exists(Path.Combine(path,".janus-drivers")));result.Add(new[]{driverSets>0?"Correcto":"Revisar","Respaldo de controladores",driverSets>0?driverSets+" respaldo(s) disponible(s).":"Aún no existe un respaldo de controladores en la carpeta predeterminada."});}catch{}
      try{var apps=InstalledApps();bool teams=apps.Any(x=>x.IndexOf("Microsoft Teams",StringComparison.OrdinalIgnoreCase)>=0)||File.Exists(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"Microsoft\WindowsApps\ms-teams.exe"));result.Add(new[]{teams?"Revisar":"Correcto","Microsoft Teams",teams?"Está instalado; revisa su inicio automático en el panel oficial.":"No se detectó Teams instalado."});bool oneDrive=apps.Any(x=>x.IndexOf("OneDrive",StringComparison.OrdinalIgnoreCase)>=0)||File.Exists(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"Microsoft\OneDrive\OneDrive.exe"));bool blocked=false;using(var key=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Policies\Microsoft\Windows\OneDrive"))blocked=key!=null&&Convert.ToInt32(key.GetValue("DisableFileSyncNGSC",0))==1;result.Add(new[]{blocked?"Correcto":oneDrive?"Revisar":"Correcto","Microsoft OneDrive",blocked?"La sincronización está desactivada por directiva.":oneDrive?"Está instalado; comprueba si deseas conservar su sincronización e inicio.":"No se detectó OneDrive."});}catch{}
      result.Add(new[]{"Revisar","Activación de Windows","Abre Activación para confirmar el estado oficial."});
      result.Add(new[]{"Revisar","Actualizaciones","Abre Windows Update y revisa también las actualizaciones opcionales."});
      return result;
    }

    static string RegistryText(RegistryKey root,string path,string name){try{using(var key=root.OpenSubKey(path))return key==null?"":Convert.ToString(key.GetValue(name));}catch{return "";}}
    public static List<string> InstalledApps(){
      var result=new SortedSet<string>(StringComparer.CurrentCultureIgnoreCase);string uninstall=@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall";
      foreach(var tuple in new[]{Tuple.Create(Registry.LocalMachine,uninstall),Tuple.Create(Registry.LocalMachine,@"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"),Tuple.Create(Registry.CurrentUser,uninstall)})try{using(var root=tuple.Item1.OpenSubKey(tuple.Item2))if(root!=null)foreach(string child in root.GetSubKeyNames())using(var app=root.OpenSubKey(child)){string name=app==null?null:Convert.ToString(app.GetValue("DisplayName"));string version=app==null?null:Convert.ToString(app.GetValue("DisplayVersion"));if(!String.IsNullOrWhiteSpace(name))result.Add(name+(String.IsNullOrWhiteSpace(version)?"":" — "+version));}}catch{}
      return result.ToList();
    }
    static string H(string value){return WebUtility.HtmlEncode(value??"");}
    public static string BuildReport(){
      string product=RegistryText(Registry.LocalMachine,@"SOFTWARE\Microsoft\Windows NT\CurrentVersion","ProductName"),display=RegistryText(Registry.LocalMachine,@"SOFTWARE\Microsoft\Windows NT\CurrentVersion","DisplayVersion"),build=RegistryText(Registry.LocalMachine,@"SOFTWARE\Microsoft\Windows NT\CurrentVersion","CurrentBuildNumber"),cpu=RegistryText(Registry.LocalMachine,@"HARDWARE\DESCRIPTION\System\CentralProcessor\0","ProcessorNameString");
      var html=new StringBuilder();html.Append("<!doctype html><html lang='es'><meta charset='utf-8'><title>Informe JANUS</title><style>body{font-family:Segoe UI,Arial;margin:34px;color:#1b2735}h1{color:#196b91}h2{border-bottom:1px solid #ccd6df;padding-bottom:5px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #d9e0e6;padding:7px;text-align:left}.ok{color:#19743c}.warn{color:#a45a00}small{color:#586b7b}</style><h1>Informe del equipo — JANUS</h1><small>Generado "+H(DateTime.Now.ToString("dd-MM-yyyy HH:mm:ss"))+" · Versión "+H(AppInfo.DisplayVersion)+"</small>");
      html.Append("<h2>Sistema</h2><table><tr><th>Equipo</th><td>"+H(Environment.MachineName)+"</td></tr><tr><th>Windows</th><td>"+H(product+" "+display+" (compilación "+build+")")+"</td></tr><tr><th>Procesador</th><td>"+H(cpu)+"</td></tr><tr><th>Arquitectura</th><td>"+(Environment.Is64BitOperatingSystem?"64 bits":"32 bits")+"</td></tr></table>");
      html.Append("<h2>Comprobación posterior</h2><table><tr><th>Estado</th><th>Elemento</th><th>Detalle</th></tr>");foreach(var row in CheckSystem())html.Append("<tr><td class='"+(row[0]=="Correcto"?"ok":"warn")+"'>"+H(row[0])+"</td><td>"+H(row[1])+"</td><td>"+H(row[2])+"</td></tr>");html.Append("</table>");
      html.Append("<h2>Unidades</h2><table><tr><th>Unidad</th><th>Tipo</th><th>Capacidad</th><th>Libre</th></tr>");foreach(var drive in DriveInfo.GetDrives().Where(d=>d.IsReady))html.Append("<tr><td>"+H(drive.Name)+"</td><td>"+H(drive.DriveType.ToString())+"</td><td>"+(drive.TotalSize/(1024L*1024L*1024L))+" GB</td><td>"+(drive.AvailableFreeSpace/(1024L*1024L*1024L))+" GB</td></tr>");html.Append("</table>");
      html.Append("<h2>Carpetas personales</h2><table><tr><th>Carpeta</th><th>Ruta actual</th></tr>");foreach(var item in new[]{Tuple.Create("Escritorio",Environment.SpecialFolder.DesktopDirectory),Tuple.Create("Documentos",Environment.SpecialFolder.MyDocuments),Tuple.Create("Imágenes",Environment.SpecialFolder.MyPictures),Tuple.Create("Música",Environment.SpecialFolder.MyMusic),Tuple.Create("Vídeos",Environment.SpecialFolder.MyVideos)})html.Append("<tr><td>"+H(item.Item1)+"</td><td>"+H(Environment.GetFolderPath(item.Item2))+"</td></tr>");html.Append("<tr><td>Descargas</td><td>"+H(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads"))+"</td></tr></table>");
      var installed=InstalledApps();html.Append("<h2>Aplicaciones registradas ("+installed.Count+")</h2><ul>");foreach(string app in installed)html.Append("<li>"+H(app)+"</li>");html.Append("</ul><h2>Paquetes de controladores de terceros</h2>");try{var drivers=Capture("pnputil.exe","/enum-drivers",60000);html.Append("<pre>"+H(drivers.Output)+"</pre>");}catch(Exception ex){html.Append("<p>No fue posible enumerarlos: "+H(ex.Message)+"</p>");}html.Append("<p><small>El informe no contiene claves de producto, contraseñas ni archivos personales.</small></p></html>");return html.ToString();
    }

    public static IEnumerable<Tuple<string,string,DateTime>> FindBackups(){
      EnsureDirectories();var result=new List<Tuple<string,string,DateTime>>();
      foreach(string file in Directory.GetFiles(Root,"*",SearchOption.AllDirectories)){if(Path.GetFileName(file)==".janus-drivers"||file.EndsWith(".jsonl",StringComparison.OrdinalIgnoreCase))continue;string type=file.EndsWith(".html",StringComparison.OrdinalIgnoreCase)?"Informe":file.EndsWith(".json",StringComparison.OrdinalIgnoreCase)?(file.IndexOf("Perfiles",StringComparison.OrdinalIgnoreCase)>=0?"Perfil de aplicaciones":"Aplicaciones"):"Archivo";result.Add(Tuple.Create(type,file,File.GetLastWriteTime(file)));}
      foreach(string directory in Directory.GetDirectories(DriversDirectory))if(File.Exists(Path.Combine(directory,".janus-drivers")))result.Add(Tuple.Create("Controladores",directory,Directory.GetLastWriteTime(directory)));
      string old=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"Respaldos Migrador Seguro");if(Directory.Exists(old))foreach(string file in Directory.GetFiles(old,"*.json"))result.Add(Tuple.Create("Rutas personales",file,File.GetLastWriteTime(file)));
      string icons=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Janus","Backups","Iconos");if(Directory.Exists(icons))foreach(string file in Directory.GetFiles(icons,"*.json"))result.Add(Tuple.Create("Iconos",file,File.GetLastWriteTime(file)));
      var known=new HashSet<string>(result.Select(x=>x.Item2),StringComparer.OrdinalIgnoreCase);foreach(var row in ReadHistory()){string path=row[4];if(String.IsNullOrWhiteSpace(path)||known.Contains(path))continue;if(Directory.Exists(path)){result.Add(Tuple.Create(row[1]=="Controladores"?"Controladores":"Carpeta",path,Directory.GetLastWriteTime(path)));known.Add(path);}else if(File.Exists(path)){string type=row[1]=="Aplicaciones"?(path.IndexOf("Perfiles",StringComparison.OrdinalIgnoreCase)>=0?"Perfil de aplicaciones":"Aplicaciones"):row[1]=="Informe"?"Informe":"Archivo";result.Add(Tuple.Create(type,path,File.GetLastWriteTime(path)));known.Add(path);}}
      return result.OrderByDescending(x=>x.Item3);
    }

    public static List<string[]> ReadKnownFolderBackup(string path){var obj=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(path,Encoding.UTF8));if(!obj.ContainsKey("folders"))throw new InvalidDataException("El archivo no contiene un respaldo de carpetas personales.");var values=obj["folders"] as Dictionary<string,object>;if(values==null)throw new InvalidDataException("El respaldo tiene un formato no compatible.");return values.Select(x=>new[]{x.Key,Convert.ToString(x.Value)}).ToList();}
