      foreach(var definition in definitions){string target;if(!values.TryGetValue(definition.Item1,out target)||String.IsNullOrWhiteSpace(target))continue;Directory.CreateDirectory(target);Guid id=new Guid(definition.Item3);int hr=SHSetKnownFolderPath(ref id,0,IntPtr.Zero,target);if(hr!=0)Marshal.ThrowExceptionForHR(hr);using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders"))key.SetValue(definition.Item2,target,RegistryValueKind.ExpandString);using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders"))key.SetValue(definition.Item2,Environment.ExpandEnvironmentVariables(target),RegistryValueKind.String);}
