    void BuildRecords(Control page){
      var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=245};page.Controls.Add(split);backups.View=View.Details;backups.FullRowSelect=true;backups.GridLines=true;backups.Columns.Add("Tipo",140);backups.Columns.Add("Fecha",135);backups.Columns.Add("Ruta",540);split.Panel1.Controls.Add(backups);backups.Dock=DockStyle.Fill;var topButtons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=40,FlowDirection=FlowDirection.LeftToRight,Padding=new Padding(4)};topButtons.Controls.Add(MakeButton("Actualizar",(s,e)=>LoadRecords(),110));topButtons.Controls.Add(MakeButton("Abrir ubicación",(s,e)=>OpenSelectedBackup(),135));topButtons.Controls.Add(MakeButton("Restaurar seleccionado…",(s,e)=>RestoreSelectedBackup(),185));split.Panel1.Controls.Add(topButtons);
      history.View=View.Details;history.FullRowSelect=true;history.GridLines=true;history.Columns.Add("Fecha",125);history.Columns.Add("Categoría",105);history.Columns.Add("Acción",170);history.Columns.Add("Resultado",120);history.Columns.Add("Ruta",280);history.Dock=DockStyle.Fill;split.Panel2.Controls.Add(history);split.Panel2.Controls.Add(new Label{Text="Historial de operaciones",Dock=DockStyle.Top,Height=24,Font=new Font("Segoe UI",9,FontStyle.Bold)});LoadRecords();
    }
    static Button MakeButton(string text,EventHandler click,int width){var b=new Button{Text=text,Width=width,Height=29};b.Click+=click;return b;}
    static void AddButton(Control parent,string text,int x,int y,EventHandler click,int width=175){var b=MakeButton(text,click,width);b.Location=new Point(x,y);parent.Controls.Add(b);}
    void SetStatus(string text){status.Text=text;status.Refresh();}
    async Task RefreshChecklist(){SetStatus("Comprobando el equipo…");checklist.Items.Clear();List<string[]> rows=null;await Task.Run(()=>rows=JanusRecovery.CheckSystem());foreach(var row in rows){var item=new ListViewItem(row[0]);item.SubItems.Add(row[1]);item.SubItems.Add(row[2]);item.ForeColor=row[0]=="Correcto"?Color.FromArgb(26,116,65):row[0]=="Atención"?Color.FromArgb(173,88,0):Color.FromArgb(64,77,90);checklist.Items.Add(item);}SetStatus("Comprobación terminada. Revisa los elementos marcados como Atención o Revisar.");}
    async void ExportApps(bool profile){
      if(!JanusRecovery.HasWinget()){MessageBox.Show("WinGet no está disponible. Actualiza 'App Installer' desde Microsoft Store y vuelve a intentarlo.","Aplicaciones",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}string path;
      if(profile){using(var prompt=new RecoveryNamePrompt()){if(prompt.ShowDialog(this)!=DialogResult.OK)return;path=Path.Combine(JanusRecovery.ProfilesDirectory,JanusRecovery.SafeName(prompt.Value)+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json");}}
      else using(var dialog=new SaveFileDialog{Filter="Lista WinGet (*.json)|*.json",InitialDirectory=JanusRecovery.AppsDirectory,FileName="Aplicaciones-"+Environment.MachineName+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;path=dialog.FileName;}
      try{SetStatus("Exportando aplicaciones con WinGet…");CommandResult result=null;await Task.Run(()=>result=JanusRecovery.Capture("winget","export -o "+JanusRecovery.Quote(path)+" --include-versions --accept-source-agreements --disable-interactivity",300000));if(result.ExitCode==0&&File.Exists(path)){int count=JanusRecovery.ReadPackageIds(path).Count;JanusRecovery.Record("Aplicaciones",profile?"Crear perfil":"Exportar lista","Correcto: "+count+" paquetes",path);MessageBox.Show("Se guardaron "+count+" paquetes reconocidos por WinGet. Los programas que no tengan coincidencia pueden aparecer como advertencias en la salida.","Aplicaciones exportadas",MessageBoxButtons.OK,MessageBoxIcon.Information);if(profile)LoadProfiles();LoadRecords();SetStatus("Lista de aplicaciones guardada.");}else{JanusRecovery.Record("Aplicaciones","Exportar lista","Error",path);MessageBox.Show("WinGet no pudo completar la exportación:\n"+result.Output,"Aplicaciones",MessageBoxButtons.OK,MessageBoxIcon.Error);SetStatus("La exportación no se completó.");}}catch(Exception ex){JanusRecovery.Record("Aplicaciones",profile?"Crear perfil":"Exportar lista","Error",path);MessageBox.Show("No se pudo exportar la lista:\n"+ex.Message,"Aplicaciones",MessageBoxButtons.OK,MessageBoxIcon.Error);SetStatus("La exportación no se completó.");}
    }
    void ImportApps(string path){if(path==null)using(var dialog=new OpenFileDialog{Filter="Lista WinGet (*.json)|*.json",InitialDirectory=JanusRecovery.AppsDirectory}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;path=dialog.FileName;}StartImport(path);}
    async void StartImport(string path){try{var ids=JanusRecovery.ReadPackageIds(path);if(ids.Count==0)throw new InvalidDataException("El archivo no contiene identificadores de paquetes WinGet.");using(var preview=new PackagePreviewForm("Aplicaciones que WinGet intentará instalar",ids))if(preview.ShowDialog(this)!=DialogResult.OK)return;if(MessageBox.Show("WinGet intentará instalar "+ids.Count+" aplicaciones. Cada instalador conserva sus propias condiciones y puede pedir permisos.\n\n¿Continuar?","Importar aplicaciones",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;SetStatus("WinGet está restaurando las aplicaciones; puedes seguir usando otras ventanas mientras termina…");CommandResult result=null;await Task.Run(()=>result=JanusRecovery.Capture("winget","import -i "+JanusRecovery.Quote(path)+" --ignore-unavailable --accept-package-agreements --accept-source-agreements",1800000));JanusRecovery.Record("Aplicaciones","Importar",result.ExitCode==0?"Correcto":"Código "+result.ExitCode,path);using(var output=new OperationOutputForm("Resultado de la importación",result.Output,result.ExitCode==0))output.ShowDialog(this);SetStatus(result.ExitCode==0?"Importación de aplicaciones terminada.":"La importación terminó con advertencias o errores.");LoadRecords();}catch(Exception ex){JanusRecovery.Record("Aplicaciones","Importar","Error",path);MessageBox.Show("No se pudo completar la importación:\n"+ex.Message,"Aplicaciones",MessageBoxButtons.OK,MessageBoxIcon.Error);SetStatus("La importación no se completó.");}}
    async void ExportDrivers(){using(var dialog=new FolderBrowserDialog{Description="Elige la unidad o carpeta donde JANUS creará el respaldo de controladores",SelectedPath=JanusRecovery.DriversDirectory})if(dialog.ShowDialog(this)==DialogResult.OK){string target=Path.Combine(dialog.SelectedPath,"Controladores-"+Environment.MachineName+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));if(MessageBox.Show("JANUS creará:\n"+target+"\n\nWindows solicitará permiso de administrador. ¿Continuar?","Exportar controladores",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;Directory.CreateDirectory(target);SetStatus("Exportando controladores…");int code=-1;try{await Task.Run(()=>code=JanusRecovery.RunElevated("pnputil.exe","/export-driver * "+JanusRecovery.Quote(target)));if(code!=0)throw new IOException("PnPUtil terminó con el código "+code+".");File.WriteAllText(Path.Combine(target,".janus-drivers"),DateTime.Now.ToString("o"));JanusRecovery.Record("Controladores","Exportar","Correcto",target);MessageBox.Show("Los controladores fueron exportados. Conserva esta carpeta fuera del disco que vas a formatear.","Controladores",MessageBoxButtons.OK,MessageBoxIcon.Information);SetStatus("Respaldo de controladores creado.");LoadRecords();}catch(Exception ex){JanusRecovery.Record("Controladores","Exportar","Error",target);MessageBox.Show("No se pudieron exportar los controladores:\n"+ex.Message,"Controladores",MessageBoxButtons.OK,MessageBoxIcon.Error);}}}
    void ChooseDrivers(){using(var dialog=new FolderBrowserDialog{Description="Selecciona un respaldo de controladores",SelectedPath=JanusRecovery.DriversDirectory})if(dialog.ShowDialog(this)==DialogResult.OK)RestoreDriverFolder(dialog.SelectedPath);}
    async void RestoreDriverFolder(string path){try{int count=Directory.GetFiles(path,"*.inf",SearchOption.AllDirectories).Length;if(count==0)throw new InvalidDataException("La carpeta no contiene controladores INF.");if(MessageBox.Show("Se encontraron "+count+" archivos INF. Windows instalará únicamente los controladores compatibles y puede solicitar un reinicio.\n\n¿Continuar?","Restaurar controladores",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;SetStatus("Restaurando controladores…");int code=-1;await Task.Run(()=>code=JanusRecovery.RunElevated("pnputil.exe","/add-driver "+JanusRecovery.Quote(Path.Combine(path,"*.inf"))+" /subdirs /install"));JanusRecovery.Record("Controladores","Restaurar",code==0?"Correcto":"Código "+code,path);MessageBox.Show(code==0?"PnPUtil terminó correctamente. Revisa el Administrador de dispositivos y reinicia si Windows lo solicita.":"PnPUtil terminó con el código "+code+". Revisa la consola y el Administrador de dispositivos.","Controladores",MessageBoxButtons.OK,code==0?MessageBoxIcon.Information:MessageBoxIcon.Warning);SetStatus("Restauración de controladores terminada.");LoadRecords();}catch(Exception ex){MessageBox.Show("No se pudieron restaurar los controladores:\n"+ex.Message,"Controladores",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    void GenerateReport(){using(var dialog=new SaveFileDialog{Filter="Informe HTML (*.html)|*.html",InitialDirectory=JanusRecovery.ReportsDirectory,FileName="Informe-JANUS-"+Environment.MachineName+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".html"})if(dialog.ShowDialog(this)==DialogResult.OK)try{SetStatus("Generando informe…");File.WriteAllText(dialog.FileName,JanusRecovery.BuildReport(),Encoding.UTF8);JanusRecovery.Record("Informe","Generar","Correcto",dialog.FileName);LoadRecords();SetStatus("Informe generado.");if(MessageBox.Show("Informe guardado. ¿Abrirlo ahora?","Informe JANUS",MessageBoxButtons.YesNo,MessageBoxIcon.Information)==DialogResult.Yes)OpenTarget(dialog.FileName);}catch(Exception ex){MessageBox.Show("No se pudo generar el informe:\n"+ex.Message,"Informe",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    async void PrepareFullBag(){using(var dialog=new FolderBrowserDialog{Description="Elige otra unidad o carpeta para guardar la Mochila completa",SelectedPath=JanusRecovery.Root})if(dialog.ShowDialog(this)==DialogResult.OK){string target=Path.Combine(dialog.SelectedPath,"Mochila-JANUS-"+Environment.MachineName+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));if(MessageBox.Show("JANUS creará una Mochila en:\n"+target+"\n\nIncluirá informe, lista de aplicaciones si WinGet está disponible y controladores. Windows solicitará permiso de administrador para los controladores. No se borrará ningún archivo.\n\n¿Continuar?","Preparar Mochila completa",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;Directory.CreateDirectory(target);var results=new List<string>();try{SetStatus("Generando el informe de la Mochila…");string report=Path.Combine(target,"Informe-JANUS.html");string html=null;await Task.Run(()=>html=JanusRecovery.BuildReport());File.WriteAllText(report,html,Encoding.UTF8);results.Add("Informe: correcto");}catch(Exception ex){results.Add("Informe: error — "+ex.Message);}if(JanusRecovery.HasWinget())try{SetStatus("Exportando la lista de aplicaciones…");string apps=Path.Combine(target,"Aplicaciones-WinGet.json");CommandResult export=null;await Task.Run(()=>export=JanusRecovery.Capture("winget","export -o "+JanusRecovery.Quote(apps)+" --include-versions --accept-source-agreements --disable-interactivity",300000));results.Add(export.ExitCode==0?"Aplicaciones: correcto":"Aplicaciones: WinGet terminó con código "+export.ExitCode);}catch(Exception ex){results.Add("Aplicaciones: error — "+ex.Message);}else results.Add("Aplicaciones: omitidas porque WinGet no está disponible");try{SetStatus("Exportando controladores…");string drivers=Path.Combine(target,"Controladores");Directory.CreateDirectory(drivers);int code=-1;await Task.Run(()=>code=JanusRecovery.RunElevated("pnputil.exe","/export-driver * "+JanusRecovery.Quote(drivers)));if(code==0){File.WriteAllText(Path.Combine(drivers,".janus-drivers"),DateTime.Now.ToString("o"));results.Add("Controladores: correcto");}else results.Add("Controladores: PnPUtil terminó con código "+code);}catch(Exception ex){results.Add("Controladores: error o autorización cancelada — "+ex.Message);}string summary="MOCHILA DE REINSTALACIÓN JANUS\r\nFecha: "+DateTime.Now.ToString("dd-MM-yyyy HH:mm:ss")+"\r\nEquipo: "+Environment.MachineName+"\r\nVersión: "+AppInfo.DisplayVersion+"\r\n\r\n"+String.Join("\r\n",results)+"\r\n\r\nConserva esta carpeta fuera del disco que vas a formatear. JANUS no elimina automáticamente estos respaldos.";File.WriteAllText(Path.Combine(target,"LEEME.txt"),summary,Encoding.UTF8);bool complete=results.All(x=>x.EndsWith("correcto",StringComparison.OrdinalIgnoreCase));JanusRecovery.Record("Mochila","Preparar paquete completo",complete?"Correcto":"Parcial",target);LoadRecords();SetStatus(complete?"Mochila completa preparada.":"La Mochila fue creada con algunos elementos pendientes.");MessageBox.Show(summary,"Resultado de la Mochila",MessageBoxButtons.OK,complete?MessageBoxIcon.Information:MessageBoxIcon.Warning);if(MessageBox.Show("¿Abrir la Mochila ahora?","Mochila JANUS",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)OpenFolder(target);}}
    void LoadProfiles(){profiles.Items.Clear();Directory.CreateDirectory(JanusRecovery.ProfilesDirectory);foreach(string path in Directory.GetFiles(JanusRecovery.ProfilesDirectory,"*.json").OrderByDescending(File.GetLastWriteTime))profiles.Items.Add(new RecoveryFileItem(path));}
    string SelectedProfile(){var item=profiles.SelectedItem as RecoveryFileItem;if(item==null)MessageBox.Show("Selecciona primero un perfil.","Perfiles",MessageBoxButtons.OK,MessageBoxIcon.Information);return item==null?null:item.Path;}
    void OpenSelectedProfile(){string path=SelectedProfile();if(path!=null)OpenTarget(path);}
    void ImportSelectedProfile(){string path=SelectedProfile();if(path!=null)StartImport(path);}
    async Task CompareSelectedProfile(){string path=SelectedProfile();if(path==null)return;if(!JanusRecovery.HasWinget()){MessageBox.Show("WinGet no está disponible. Usa 'Obtener WinGet' en la pestaña Mochila.","Comparar perfil",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}string temporary=Path.Combine(Path.GetTempPath(),"janus-comparacion-"+Guid.NewGuid().ToString("N")+".json");try{SetStatus("Comparando el perfil con las aplicaciones instaladas…");CommandResult result=null;await Task.Run(()=>result=JanusRecovery.Capture("winget","export -o "+JanusRecovery.Quote(temporary)+" --include-versions --accept-source-agreements --disable-interactivity",300000));if(result.ExitCode!=0||!File.Exists(temporary))throw new IOException("WinGet no pudo obtener la lista actual.\n"+result.Output);var expected=JanusRecovery.ReadPackageIds(path);var current=new HashSet<string>(JanusRecovery.ReadPackageIds(temporary),StringComparer.OrdinalIgnoreCase);var missing=expected.Where(id=>!current.Contains(id)).ToList();JanusRecovery.Record("Perfiles","Comparar",missing.Count==0?"Completo":"Faltan "+missing.Count,path);if(missing.Count==0)MessageBox.Show("Todas las aplicaciones reconocidas del perfil aparecen instaladas.","Comparar perfil",MessageBoxButtons.OK,MessageBoxIcon.Information);else using(var preview=new PackagePreviewForm("Aplicaciones del perfil que no aparecen instaladas",missing))preview.ShowDialog(this);SetStatus("Comparación terminada: "+missing.Count+" aplicación(es) pendiente(s).");LoadRecords();}catch(Exception ex){MessageBox.Show("No se pudo comparar el perfil:\n"+ex.Message,"Comparar perfil",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{try{if(File.Exists(temporary))File.Delete(temporary);}catch{}}}
    void LoadRecords(){backups.Items.Clear();foreach(var item in JanusRecovery.FindBackups()){var row=new ListViewItem(item.Item1);row.SubItems.Add(item.Item3.ToString("dd-MM-yyyy HH:mm"));row.SubItems.Add(item.Item2);row.Tag=item.Item2;backups.Items.Add(row);}history.Items.Clear();foreach(var row in JanusRecovery.ReadHistory()){var item=new ListViewItem(row[0]);for(int i=1;i<row.Length;i++)item.SubItems.Add(row[i]);history.Items.Add(item);}}
    string SelectedBackup(){if(backups.SelectedItems.Count==0){MessageBox.Show("Selecciona primero un respaldo.","Respaldos",MessageBoxButtons.OK,MessageBoxIcon.Information);return null;}return Convert.ToString(backups.SelectedItems[0].Tag);}
    void OpenSelectedBackup(){string path=SelectedBackup();if(path!=null)OpenFolder(Directory.Exists(path)?path:Path.GetDirectoryName(path));}
    void RestoreSelectedBackup(){string path=SelectedBackup();if(path==null)return;string type=backups.SelectedItems[0].Text;if(type=="Aplicaciones"||type=="Perfil de aplicaciones")StartImport(path);else if(type=="Controladores")RestoreDriverFolder(path);else if(type=="Informe")OpenTarget(path);else if(type=="Rutas personales")RestoreKnownFolderBackup(path);else if(type=="Iconos")using(var form=new JanusIconThemeForm())form.ShowDialog(this);else{OpenFolder(Directory.Exists(path)?path:Path.GetDirectoryName(path));MessageBox.Show("JANUS abrió la ubicación. Este elemento no tiene una restauración automática asociada.","Respaldos",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
    void RestoreKnownFolderBackup(string path){try{var rows=JanusRecovery.ReadKnownFolderBackup(path);using(var preview=new PackagePreviewForm("Rutas personales que serán restauradas",rows.Select(x=>x[0]+" → "+x[1])))if(preview.ShowDialog(this)!=DialogResult.OK)return;if(MessageBox.Show("Se restaurarán únicamente las rutas registradas en Windows. JANUS no moverá ni borrará archivos.\n\n¿Continuar?","Restaurar rutas personales",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;JanusRecovery.RestoreKnownFolders(path);MessageBox.Show("Las rutas personales fueron restauradas. Cierra sesión o reinicia el Explorador para ver todos los cambios.","Rutas restauradas",MessageBoxButtons.OK,MessageBoxIcon.Information);LoadRecords();}catch(Exception ex){JanusRecovery.Record("Rutas personales","Restaurar","Error",path);MessageBox.Show("No se pudieron restaurar las rutas:\n"+ex.Message,"Rutas personales",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    static void OpenFolder(string path){try{Directory.CreateDirectory(path);Process.Start(new ProcessStartInfo("explorer.exe",JanusRecovery.Quote(path)){UseShellExecute=true});}catch(Exception ex){MessageBox.Show("No se pudo abrir la carpeta:\n"+ex.Message,"JANUS",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    static void OpenTarget(string target){try{Process.Start(new ProcessStartInfo(target){UseShellExecute=true});}catch(Exception ex){MessageBox.Show("No se pudo abrir:\n"+ex.Message,"JANUS",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
  }

  sealed class RecoveryFileItem { public string Path; public string Name; public RecoveryFileItem(string path){Path=path;Name=System.IO.Path.GetFileNameWithoutExtension(path);}public override string ToString(){return Name;} }
  sealed class RecoveryNamePrompt:Form {readonly TextBox input=new TextBox();public string Value{get{return input.Text;}}public RecoveryNamePrompt(){Text="Nuevo perfil";ClientSize=new Size(410,145);StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;Controls.Add(new Label{Text="Nombre del perfil de aplicaciones:",Location=new Point(18,18),AutoSize=true});input.SetBounds(18,45,374,27);Controls.Add(input);var ok=new Button{Text="Crear",DialogResult=DialogResult.OK,Location=new Point(218,94),Size=new Size(82,29)};var cancel=new Button{Text="Cancelar",DialogResult=DialogResult.Cancel,Location=new Point(310,94),Size=new Size(82,29)};Controls.Add(ok);Controls.Add(cancel);AcceptButton=ok;CancelButton=cancel;Shown+=(s,e)=>input.Focus();}}
