  sealed class OperationOutputForm:Form {public OperationOutputForm(string title,string output,bool success){Text=title;ClientSize=new Size(700,500);StartPosition=FormStartPosition.CenterParent;Controls.Add(new Label{Text=success?"Operación completada":"La operación terminó con advertencias o errores",Font=new Font("Segoe UI",13,FontStyle.Bold),ForeColor=success?Color.FromArgb(26,116,65):Color.FromArgb(173,88,0),Location=new Point(18,15),AutoSize=true});Controls.Add(new TextBox{Text=output,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,BackColor=Color.White,Font=new Font("Consolas",9),Location=new Point(18,52),Size=new Size(664,390)});var close=new Button{Text="Cerrar",DialogResult=DialogResult.OK,Location=new Point(562,454),Size=new Size(120,30)};Controls.Add(close);AcceptButton=close;}}
